import urllib.request
import urllib.error
import time
import json


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        # Rate limit retries: up to 3 times with exponential backoff
        rate_limit_retries = 3
        rate_limit_delays = [0.5, 1.0, 2.0]

        # Server error retries: up to 1 retry (total 2 attempts)
        server_retries = 1
        server_delay = 1.0

        # Network error retries: up to 1 retry (total 2 attempts)
        network_retries = 1
        network_delay = 1.0

        # Track attempts for rate limiting
        rate_limit_attempt = 0
        server_attempt = 0
        network_attempt = 0

        while True:
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status_code = response.status
                    if status_code == 200:
                        body = response.read().decode('utf-8')
                        return body
                    elif status_code == 429:
                        if rate_limit_attempt < rate_limit_retries:
                            delay = rate_limit_delays[rate_limit_attempt]
                            rate_limit_attempt += 1
                            time.sleep(delay)
                            continue
                        else:
                            raise RateLimitError("Rate limit exceeded")
                    elif 500 <= status_code < 600:
                        if server_attempt < server_retries:
                            server_attempt += 1
                            time.sleep(server_delay)
                            continue
                        else:
                            raise ServerError(f"Server error: {status_code}")
                    elif 400 <= status_code < 500:
                        raise ClientError(f"Client error: {status_code}")
                    else:
                        # Other status codes, treat as error
                        body = response.read().decode('utf-8')
                        return body

            except urllib.error.HTTPError as e:
                status_code = e.code
                if status_code == 429:
                    if rate_limit_attempt < rate_limit_retries:
                        delay = rate_limit_delays[rate_limit_attempt]
                        rate_limit_attempt += 1
                        time.sleep(delay)
                        continue
                    else:
                        raise RateLimitError("Rate limit exceeded")
                elif 500 <= status_code < 600:
                    if server_attempt < server_retries:
                        server_attempt += 1
                        time.sleep(server_delay)
                        continue
                    else:
                        raise ServerError(f"Server error: {status_code}")
                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error: {status_code}")
                else:
                    raise

            except urllib.error.URLError as e:
                if network_attempt < network_retries:
                    network_attempt += 1
                    time.sleep(network_delay)
                    continue
                else:
                    raise ConnectionError(f"Connection error: {e}")

            except Exception as e:
                raise
